pair O, A, B;

O = (0,0);
A = dir(20);
B = dir(80);

draw((-0.2,0)--(1,0));
draw((0,-0.2)--(0,1));
draw(O--A--B--cycle);

label("$(a,y)$", A, E);
label("$(x,b)$", B, N);
